package app.kozica.ui.map

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.boolean
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.double
import kotlinx.serialization.json.float
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import kotlinx.serialization.json.put
import java.io.File

/** Generated by `scripts/map/gen_style.py`. */
internal fun styleTemplate(dark: Boolean): String = if (dark) "map/style-dark.json" else "map/style-light.json"

/**
 * The template with one source per ready Region and each Region-sourced layer repeated per Region,
 * in the template's layer order, so one Region's land never paints over another's Trails
 * (docs/phase-2.md § 2). The relief's layers are drawn once, from [relief] and the contours beside
 * it, and dropped while it has not arrived (docs/phase-4.md § 3). A layer whose source the template
 * itself defines, the Route's or the Regions' outlines, is drawn once too.
 */
internal fun expandStyle(
    template: String,
    archives: List<Pair<String, File>>,
    relief: File? = null,
): String {
    val style = Json.parseToJsonElement(template).jsonObject
    val own = style["sources"]?.jsonObject?.keys.orEmpty()
    val sources =
        buildJsonObject {
            style["sources"]?.jsonObject?.forEach { (id, source) -> put(id, source) }
            for ((region, archive) in archives) {
                put(region, pmtiles("vector", archive))
            }
            if (relief != null) {
                put(
                    RELIEF_SOURCE,
                    JsonObject(
                        pmtiles("raster-dem", relief) +
                            mapOf("encoding" to JsonPrimitive("terrarium"), "tileSize" to JsonPrimitive(512)),
                    ),
                )
                put(CONTOURS_SOURCE, pmtiles("vector", relief.resolveSibling("contours.pmtiles")))
            }
        }
    val layers =
        style.getValue("layers").jsonArray.flatMap { element ->
            val layer = element.jsonObject
            val source = layer["source"]?.jsonPrimitive?.content
            when {
                source == null || source in own -> listOf(layer)
                source == RELIEF_SOURCE || source == CONTOURS_SOURCE -> listOfNotNull(layer.takeIf { relief != null })
                else ->
                    archives.map { (region, _) ->
                        val id = layer.getValue("id").jsonPrimitive.content
                        JsonObject(
                            layer + mapOf("id" to JsonPrimitive("$id-$region"), "source" to JsonPrimitive(region)),
                        )
                    }
            }
        }
    return JsonObject(style + mapOf("sources" to sources, "layers" to JsonArray(layers))).toString()
}

/** Where the camera may go: the Regions' bounds, written by `scripts/map/gen_regions.py`. */
internal data class CameraBounds(
    val west: Double,
    val south: Double,
    val east: Double,
    val north: Double,
) {
    fun contains(
        latitude: Double,
        longitude: Double,
    ) = latitude in south..north && longitude in west..east
}

internal fun cameraBoundsOf(style: String): CameraBounds {
    val (west, south, east, north) =
        Json
            .parseToJsonElement(style)
            .jsonObject
            .getValue("metadata")
            .jsonObject
            .getValue("kozica:bounds")
            .jsonArray
            .map { it.jsonPrimitive.double }
    return CameraBounds(west, south, east, north)
}

/** The layers a shown Route fades, by their expanded ids, and the opacity they fade to. */
internal data class Fade(
    val layers: List<String>,
    val opacity: Float,
)

internal fun fadeOf(style: String): Fade {
    val json = Json.parseToJsonElement(style).jsonObject
    val layers =
        json.getValue("layers").jsonArray.map { it.jsonObject }.filter {
            it["metadata"]
                ?.jsonObject
                ?.get("kozica:fade")
                ?.jsonPrimitive
                ?.boolean == true
        }
    val opacity =
        json
            .getValue("metadata")
            .jsonObject
            .getValue("kozica:faded-opacity")
            .jsonPrimitive.float
    return Fade(layers.map { it.getValue("id").jsonPrimitive.content }, opacity)
}

private fun pmtiles(
    type: String,
    archive: File,
) = buildJsonObject {
    put("type", type)
    put("url", "pmtiles://file://${archive.absolutePath}")
}

private const val RELIEF_SOURCE = "relief"
private const val CONTOURS_SOURCE = "contours"
internal const val ROUTE_SOURCE = "route"
